import{_ as a,o as n,c as p,ag as t}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"认识论与科学哲学：知识的边界","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/philosophy/epistemology.md","filePath":"topics/philosophy/epistemology.md"}'),l={name:"topics/philosophy/epistemology.md"};function e(i,s,o,d,c,r){return n(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="认识论与科学哲学-知识的边界" tabindex="-1">认识论与科学哲学：知识的边界 <a class="header-anchor" href="#认识论与科学哲学-知识的边界" aria-label="Permalink to &quot;认识论与科学哲学：知识的边界&quot;">​</a></h1><blockquote><p>我们能知道什么？知识从何而来？科学为什么可靠？这些追问构成哲学中最&quot;烧脑&quot;却也最实用的领域——<strong>认识论（Epistemology）<strong>和</strong>科学哲学（Philosophy of Science）</strong>。它们不仅是学术问题，更是每个人每天都在面对的：如何判断一条消息的真假？如何建立可信的判断？</p><p>整理日期：2026-06-17</p></blockquote><hr><h2 id="一、什么是知识" tabindex="-1">一、什么是知识 <a class="header-anchor" href="#一、什么是知识" aria-label="Permalink to &quot;一、什么是知识&quot;">​</a></h2><h3 id="_1-1-知识的经典定义-柏拉图三元组" tabindex="-1">1.1 知识的经典定义：柏拉图三元组 <a class="header-anchor" href="#_1-1-知识的经典定义-柏拉图三元组" aria-label="Permalink to &quot;1.1 知识的经典定义：柏拉图三元组&quot;">​</a></h3><p><strong>柏拉图</strong>（约公元前428-前348）提出知识的经典定义：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>知识 = 信念（Belief）+ 证据（Justification）+ 证真（Truth）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三者缺一不可：</span></span>
<span class="line"><span>✗ 信念但不证真 → &quot;我相信地球是平的&quot;，但这是错的 → 不是知识</span></span>
<span class="line"><span>✗ 有证据但不信念 → &quot;科学家证明地球是圆的&quot;，但我不信 → 不是知识</span></span>
<span class="line"><span>✓ 三者齐备 → 相信地球是圆的，且有科学证据，且地球确实是圆的 → 知识</span></span></code></pre></div><h3 id="_1-2-知识的来源问题" tabindex="-1">1.2 知识的来源问题 <a class="header-anchor" href="#_1-2-知识的来源问题" aria-label="Permalink to &quot;1.2 知识的来源问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>知识从哪里来？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>理性主义：知识来自理性/先天观念</span></span>
<span class="line"><span>  代表：柏拉图、笛卡尔、康德</span></span>
<span class="line"><span>  例：数学真理 = 理性推导，不需要经验</span></span>
<span class="line"><span></span></span>
<span class="line"><span>经验主义：知识来自感官经验</span></span>
<span class="line"><span>  代表：亚里士多德、休谟、洛克</span></span>
<span class="line"><span>  例：科学真理 = 观察实验归纳</span></span>
<span class="line"><span></span></span>
<span class="line"><span>辩证唯物主义：知识来自实践</span></span>
<span class="line"><span>  代表：马克思、毛泽东</span></span>
<span class="line"><span>  例：认识从实践中来，到实践中去</span></span>
<span class="line"><span>  参见：[毛泽东哲学《实践论》](../mao-zedong/mao-philosophy-practice-contradiction.md)</span></span></code></pre></div><hr><h2 id="二、可知论-vs-怀疑论" tabindex="-1">二、可知论 vs 怀疑论 <a class="header-anchor" href="#二、可知论-vs-怀疑论" aria-label="Permalink to &quot;二、可知论 vs 怀疑论&quot;">​</a></h2><h3 id="_2-1-核心对立" tabindex="-1">2.1 核心对立 <a class="header-anchor" href="#_2-1-核心对立" aria-label="Permalink to &quot;2.1 核心对立&quot;">​</a></h3><table tabindex="0"><thead><tr><th>立场</th><th>主张</th><th>代表人物</th></tr></thead><tbody><tr><td><strong>可知论</strong></td><td>我们能够认识世界的真实面貌</td><td>大多数哲学家</td></tr><tr><td><strong>怀疑论</strong></td><td>我们的认识能力有限，无法获得确定知识</td><td>皮浪、休谟、笛卡尔（方法论怀疑）</td></tr></tbody></table><h3 id="_2-2-怀疑论的核心挑战" tabindex="-1">2.2 怀疑论的核心挑战 <a class="header-anchor" href="#_2-2-怀疑论的核心挑战" aria-label="Permalink to &quot;2.2 怀疑论的核心挑战&quot;">​</a></h3><p><strong>休谟的怀疑论三连：</strong></p><ol><li><p><strong>归纳问题：</strong></p><blockquote><p>太阳过去每天升起 → 太阳明天会升起？ 这是归纳推理，但归纳本身无法被证明。 逻辑上，太阳明天可能不升起！</p></blockquote></li><li><p><strong>因果难题：</strong></p><blockquote><p>我们看到的只是&quot;先后发生&quot;，不是&quot;因果关系&quot;。 雨伞撑开 + 雨停了 ≠ 雨伞导致雨停（只是同时发生） 因果只是心理习惯，不是逻辑必然。</p></blockquote></li><li><p><strong>外部世界存在吗？</strong></p><blockquote><p>可能是梦境——你无法证明此刻不是梦。 （&quot;缸中之脑&quot;思想实验）</p></blockquote></li></ol><h3 id="_2-3-笛卡尔的回应-方法论怀疑" tabindex="-1">2.3 笛卡尔的回应：方法论怀疑 <a class="header-anchor" href="#_2-3-笛卡尔的回应-方法论怀疑" aria-label="Permalink to &quot;2.3 笛卡尔的回应：方法论怀疑&quot;">​</a></h3><p><strong>笛卡尔的策略：</strong> 怀疑一切，看什么无法被怀疑。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>怀疑一切：</span></span>
<span class="line"><span>- 感官可能欺骗我 → 怀疑感官</span></span>
<span class="line"><span>- 数学可能有人让我出错 → 怀疑数学</span></span>
<span class="line"><span>- 可能我只是一直在做梦 → 怀疑现实</span></span>
<span class="line"><span></span></span>
<span class="line"><span>唯一无法怀疑的：</span></span>
<span class="line"><span>- &quot;我在怀疑&quot;这件事本身</span></span>
<span class="line"><span>- 即：&quot;我思故我在&quot;（Cogito ergo sum）</span></span></code></pre></div><blockquote><p>虽然我可能一切都是假的，但&quot;我正在思考&quot;这件事本身是真的。 这是认识的阿基米德点。</p></blockquote><h3 id="_2-4-辩证唯物论的回应" tabindex="-1">2.4 辩证唯物论的回应 <a class="header-anchor" href="#_2-4-辩证唯物论的回应" aria-label="Permalink to &quot;2.4 辩证唯物论的回应&quot;">​</a></h3><p><strong>马克思、恩格斯的立场：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>怀疑论的贡献：指出认识的相对性</span></span>
<span class="line"><span>辩证唯物论的回应：</span></span>
<span class="line"><span>  - 承认认识的相对性，但不陷入虚无主义</span></span>
<span class="line"><span>  - 真理是不断接近的过程</span></span>
<span class="line"><span>  - 实践是检验真理的唯一标准</span></span></code></pre></div><blockquote><p>毛泽东《实践论》深化了这一观点：认识的相对性不等于&quot;什么都不能知道&quot;，而是认识是一个不断发展深化的过程。参见：<a href="/zhishiku-reading/topics/mao-zedong/mao-philosophy-practice-contradiction.html">毛泽东哲学：实践论</a></p></blockquote><hr><h2 id="三、科学哲学-科学为什么可靠" tabindex="-1">三、科学哲学：科学为什么可靠 <a class="header-anchor" href="#三、科学哲学-科学为什么可靠" aria-label="Permalink to &quot;三、科学哲学：科学为什么可靠&quot;">​</a></h2><h3 id="_3-1-波普尔-可证伪性" tabindex="-1">3.1 波普尔：可证伪性 <a class="header-anchor" href="#_3-1-波普尔-可证伪性" aria-label="Permalink to &quot;3.1 波普尔：可证伪性&quot;">​</a></h3><p><strong>卡尔·波普尔</strong>（1902-1994）提出科学最重要的特征：<strong>可证伪性（Falsifiability）</strong>。</p><p><strong>核心思想：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>科学理论必须能够被反驳/证伪</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可证伪 ≠ 会错</span></span>
<span class="line"><span>可证伪 = 存在一种可能的情况，如果发生，理论就被推翻</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可证伪的例子：</span></span>
<span class="line"><span>- &quot;所有天鹅都是白的&quot; → 发现一只黑天鹅 → 被证伪 ✓</span></span>
<span class="line"><span>- &quot;地球是圆的&quot; → 可以设计实验验证，也可以被推翻 ✓</span></span>
<span class="line"><span>- &quot;明天的股市会涨或跌&quot; → 两种可能都算对 → 不可证伪 ✗</span></span></code></pre></div><p><strong>伪科学的特征：</strong></p><ul><li>无法被证伪（总是能自圆其说）</li><li>拒绝接受反驳证据</li><li>使用模糊语言避免被检验</li></ul><h3 id="_3-2-库恩-范式转换" tabindex="-1">3.2 库恩：范式转换 <a class="header-anchor" href="#_3-2-库恩-范式转换" aria-label="Permalink to &quot;3.2 库恩：范式转换&quot;">​</a></h3><p><strong>托马斯·库恩</strong>（1922-1996）的《科学革命的结构》改变了我们对科学发展的理解。</p><p><strong>范式（Paradigm）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>范式 = 某一时期科学共同体共同接受的理论框架、方法、问题域</span></span>
<span class="line"><span></span></span>
<span class="line"><span>常规科学：</span></span>
<span class="line"><span>  在范式内解题（&quot;解谜&quot;）</span></span>
<span class="line"><span>  ↓ 遇到无法解释的异常</span></span>
<span class="line"><span>  危机</span></span>
<span class="line"><span>  ↓ 出现新的竞争框架</span></span>
<span class="line"><span>  革命</span></span>
<span class="line"><span>  ↓ 新范式取代旧范式</span></span>
<span class="line"><span>  新的常规科学开始...</span></span></code></pre></div><p><strong>历史上的范式转换：</strong></p><table tabindex="0"><thead><tr><th>旧范式</th><th>新范式</th><th>革命标志</th></tr></thead><tbody><tr><td>地心说</td><td>日心说</td><td>哥白尼</td></tr><tr><td>牛顿力学</td><td>相对论</td><td>爱因斯坦</td></tr><tr><td>经典物理</td><td>量子物理</td><td>普朗克</td></tr></tbody></table><h3 id="_3-3-拉卡托斯-研究纲领" tabindex="-1">3.3 拉卡托斯：研究纲领 <a class="header-anchor" href="#_3-3-拉卡托斯-研究纲领" aria-label="Permalink to &quot;3.3 拉卡托斯：研究纲领&quot;">​</a></h3><p><strong>伊姆雷·拉卡托斯</strong>（1922-1974）发展了更精细的科学评价框架。</p><p><strong>研究纲领（Research Programme）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个科学研究纲领包含：</span></span>
<span class="line"><span>- 硬核（Hard Core）：不可反驳的核心假设</span></span>
<span class="line"><span>  例：牛顿力学的核心——力是物体运动的原因</span></span>
<span class="line"><span>- 保护带（Protective Belt）：可调整的辅助假设</span></span>
<span class="line"><span>  例：摩擦力、空气阻力等</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当异常出现时，先调整保护带</span></span>
<span class="line"><span>只有硬核被证伪时，才放弃整个纲领</span></span></code></pre></div><hr><h2 id="四、批判性思维-如何判断信息真伪" tabindex="-1">四、批判性思维：如何判断信息真伪 <a class="header-anchor" href="#四、批判性思维-如何判断信息真伪" aria-label="Permalink to &quot;四、批判性思维：如何判断信息真伪&quot;">​</a></h2><h3 id="_4-1-认知偏差清单" tabindex="-1">4.1 认知偏差清单 <a class="header-anchor" href="#_4-1-认知偏差清单" aria-label="Permalink to &quot;4.1 认知偏差清单&quot;">​</a></h3><p><strong>每个人都会犯的思维错误：</strong></p><table tabindex="0"><thead><tr><th>偏差</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td><strong>确认偏误</strong></td><td>只看到支持自己观点的证据</td><td>认为中医有效，只记住治好的案例</td></tr><tr><td><strong>可得性启发</strong></td><td>以为常见的事更可能发生</td><td>飞机失事很少，但感觉很常见</td></tr><tr><td><strong>后见之明</strong></td><td>事后觉得&quot;早就知道会这样&quot;</td><td>事后诸葛亮</td></tr><tr><td><strong>锚定效应</strong></td><td>被第一印象影响判断</td><td>谈判时先开口的人占优势</td></tr><tr><td><strong>过度自信</strong></td><td>高估自己判断的准确度</td><td>90%的司机认为自己的驾驶技术高于平均水平</td></tr></tbody></table><h3 id="_4-2-逻辑谬误清单" tabindex="-1">4.2 逻辑谬误清单 <a class="header-anchor" href="#_4-2-逻辑谬误清单" aria-label="Permalink to &quot;4.2 逻辑谬误清单&quot;">​</a></h3><p><strong>常见论证错误：</strong></p><table tabindex="0"><thead><tr><th>谬误</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td><strong>诉诸权威</strong></td><td>&quot;专家说的，所以是对的&quot;</td><td>权威也可能错，需要看论证</td></tr><tr><td><strong>诉诸情感</strong></td><td>用情感代替论证</td><td>&quot;你不支持就是冷血&quot;</td></tr><tr><td><strong>人身攻击</strong></td><td>攻击人，不攻击论点</td><td>&quot;他品格有问题，所以观点错&quot;</td></tr><tr><td><strong>稻草人</strong></td><td>曲解对方论点再反驳</td><td>&quot;你说要自由，就是说可以杀人？&quot;</td></tr><tr><td><strong>滑坡</strong></td><td>不给底线，一路下滑</td><td>&quot;今天允许A，明天就允许B，后天就是世界末日&quot;</td></tr><tr><td><strong>循环论证</strong></td><td>用结论证明前提</td><td>&quot;上帝存在，因为圣经说的；圣经可信，因为上帝写的&quot;</td></tr></tbody></table><h3 id="_4-3-批判性思维的操作步骤" tabindex="-1">4.3 批判性思维的操作步骤 <a class="header-anchor" href="#_4-3-批判性思维的操作步骤" aria-label="Permalink to &quot;4.3 批判性思维的操作步骤&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>面对任何观点，用这个流程检验：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第一步：这是什么观点？</span></span>
<span class="line"><span>  - 用一句话复述对方观点</span></span>
<span class="line"><span>  - 确认自己理解正确</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二步：证据是什么？</span></span>
<span class="line"><span>  - 谁说的？可靠吗？</span></span>
<span class="line"><span>  - 样本够大吗？控制变量了吗？</span></span>
<span class="line"><span>  - 来源是什么？有没有利益关联？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三步：推理有效吗？</span></span>
<span class="line"><span>  - 从证据到结论，逻辑通顺吗？</span></span>
<span class="line"><span>  - 有没有逻辑跳跃？</span></span>
<span class="line"><span>  - 有没有其他解释？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第四步：有没有反驳？</span></span>
<span class="line"><span>  - 反面证据是什么？</span></span>
<span class="line"><span>  - 有人做过反驳吗？</span></span>
<span class="line"><span>  - 我的结论是否过于绝对？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第五步：我的立场是什么？</span></span>
<span class="line"><span>  - 在相信与不相信之间，我如何取舍？</span></span>
<span class="line"><span>  - 我愿意多大程度地相信？</span></span>
<span class="line"><span>  - 需要什么新证据可以改变我的立场？</span></span></code></pre></div><hr><h2 id="五、认识论的现实应用" tabindex="-1">五、认识论的现实应用 <a class="header-anchor" href="#五、认识论的现实应用" aria-label="Permalink to &quot;五、认识论的现实应用&quot;">​</a></h2><h3 id="_5-1-如何判断新闻真假" tabindex="-1">5.1 如何判断新闻真假 <a class="header-anchor" href="#_5-1-如何判断新闻真假" aria-label="Permalink to &quot;5.1 如何判断新闻真假&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>假新闻识别清单：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 来源检查</span></span>
<span class="line"><span>   - 这个媒体/账号可靠吗？</span></span>
<span class="line"><span>   - 有没有其他可靠来源确认？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 内容检查</span></span>
<span class="line"><span>   - 图片是PS的吗？视频是什么时候的？</span></span>
<span class="line"><span>   - 数据有没有上下文？</span></span>
<span class="line"><span>   - 是观点还是事实？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 动机检查</span></span>
<span class="line"><span>   - 发布者有什么目的？</span></span>
<span class="line"><span>   - 煽动情绪还是提供信息？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 逻辑检查</span></span>
<span class="line"><span>   - 论证符合逻辑吗？</span></span>
<span class="line"><span>   - 符合常识吗？</span></span></code></pre></div><h3 id="_5-2-如何建立可信判断" tabindex="-1">5.2 如何建立可信判断 <a class="header-anchor" href="#_5-2-如何建立可信判断" aria-label="Permalink to &quot;5.2 如何建立可信判断&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>判断的可信度分层：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高可信度（可直接接受）：</span></span>
<span class="line"><span>  ✓ 多方独立来源一致确认</span></span>
<span class="line"><span>  ✓ 有原始数据/一手证据</span></span>
<span class="line"><span>  ✓ 符合已知事实框架</span></span>
<span class="line"><span></span></span>
<span class="line"><span>中等可信度（审慎接受）：</span></span>
<span class="line"><span>  ~ 单个权威来源</span></span>
<span class="line"><span>  ~ 符合直觉但未经充分验证</span></span>
<span class="line"><span>  ~ 有反例但比例小</span></span>
<span class="line"><span></span></span>
<span class="line"><span>低可信度（保留怀疑）：</span></span>
<span class="line"><span>  ✗ 来源单一，无法核实</span></span>
<span class="line"><span>  ✗ 与已知事实框架矛盾</span></span>
<span class="line"><span>  ✗ 动机可疑</span></span></code></pre></div><h3 id="_5-3-投资决策中的认识论" tabindex="-1">5.3 投资决策中的认识论 <a class="header-anchor" href="#_5-3-投资决策中的认识论" aria-label="Permalink to &quot;5.3 投资决策中的认识论&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>投资判断的错误模式：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>确认偏误：</span></span>
<span class="line"><span>  只看利好消息，忽视利空信号</span></span>
<span class="line"><span></span></span>
<span class="line"><span>后见之明：</span></span>
<span class="line"><span>  后悔&quot;早知道&quot;——其实是无法预测的</span></span>
<span class="line"><span></span></span>
<span class="line"><span>过度自信：</span></span>
<span class="line"><span>  &quot;我知道这只股票会涨&quot;——实际上无法确定</span></span>
<span class="line"><span></span></span>
<span class="line"><span>锚定效应：</span></span>
<span class="line"><span>  死死盯住买入价，不愿止损</span></span></code></pre></div><hr><h2 id="六、知识论的核心原则" tabindex="-1">六、知识论的核心原则 <a class="header-anchor" href="#六、知识论的核心原则" aria-label="Permalink to &quot;六、知识论的核心原则&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>认识论总结（六条原则）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 知识需要证据支持</span></span>
<span class="line"><span>   → 没有证据的信念不是知识</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 证据需要可检验</span></span>
<span class="line"><span>   → 不可检验的主张无法判断真假</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 知识是开放的</span></span>
<span class="line"><span>   → 任何知识都可能被修正</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 实践是检验的标准</span></span>
<span class="line"><span>   → 思想的效果需要在行动中验证</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5. 承认不确定性</span></span>
<span class="line"><span>   → 不确定不等于不知道</span></span>
<span class="line"><span></span></span>
<span class="line"><span>6. 持续追问</span></span>
<span class="line"><span>   → 苏格拉底式追问是最好的思维习惯</span></span></code></pre></div><hr><h2 id="七、与毛泽东哲学的呼应" tabindex="-1">七、与毛泽东哲学的呼应 <a class="header-anchor" href="#七、与毛泽东哲学的呼应" aria-label="Permalink to &quot;七、与毛泽东哲学的呼应&quot;">​</a></h2><blockquote><p>毛泽东《实践论》的认识论框架与波普尔的证伪主义有有趣的对话空间。</p></blockquote><table tabindex="0"><thead><tr><th>维度</th><th>波普尔（证伪主义）</th><th>毛泽东（实践论）</th></tr></thead><tbody><tr><td><strong>理论地位</strong></td><td>猜想，迟早被证伪</td><td>理性认识，来源于实践</td></tr><tr><td><strong>检验标准</strong></td><td>可证伪性 + 暂时未被证伪</td><td>实践检验</td></tr><tr><td><strong>科学发展</strong></td><td>范式革命，猜想→反驳→新猜想</td><td>实践→认识→再实践</td></tr><tr><td><strong>共同点</strong></td><td>都强调知识的可错性和开放性</td><td></td></tr></tbody></table><hr><p><em>整理日期：2026-06-17</em><em>建议交叉阅读：</em></p><ul><li><em>毛泽东哲学《实践论》（认识从实践中来）</em></li><li><em>毛泽东哲学《矛盾论》（分析问题的辩证法）</em></li><li><em>实用主义哲学（杜威的工具主义与认识论的关系）</em></li><li><em>西方哲学（笛卡尔、休谟的近代认识论传统）</em></li></ul>`,70)])])}const g=a(l,[["render",e]]);export{u as __pageData,g as default};
